    const saved = await saveHostSessionRecapSummary(sessionId, summaryText, status);
    return {
      summaryText:
        typeof saved.summaryText === 'string' ? saved.summaryText : summaryText,
      summaryStatus:
        saved.summaryStatus === 'approved'
          ? 'approved'
          : saved.summaryStatus === 'draft'
            ? 'draft'
            : status,
    };
  }
}

